import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"萃","description":"周易集解 - 萃","frontmatter":{"title":"萃","description":"周易集解 - 萃"},"headers":[],"relativePath":"zh/classics/jijie/045.md","filePath":"zh/classics/jijie/045.md"}'),l={name:"zh/classics/jijie/045.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="萃" tabindex="-1">萃 <a class="header-anchor" href="#萃" aria-label="Permalink to “萃”">​</a></h1><h2 id="萃-1" tabindex="-1">萃 <a class="header-anchor" href="#萃-1" aria-label="Permalink to “萃”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>萃，亨，王假有廟。利見大人，亨，利貞。用大牲吉，利有攸往。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：物相遇而後聚，故受之以萃。萃者，聚也。</p><p>崔憬曰：天地相遇，品物咸章，故言物相遇而後聚。</p><p>虞翻曰：觀上之四也。觀乾為王。假，至也。艮為廟，體觀享祀，上之四，故｢假有廟，致孝享｣矣。</p><p>虞翻曰：大人謂五。三四失位，利之正。變成離，離為見。故｢利見大人，亨，利貞｣。聚以正也。</p><p>虞翻曰：坤為牛，故曰大牲，四之三，折坤得正，故用大牲吉。三往之四，故｢利有攸往，順天命也｣。</p><p>鄭玄曰：萃，聚也。坤為順。兌為悅。臣下以順道承事其君，說德居上待之。上下相應，有事而和通，故曰萃亨也。假，至也。互有艮巽，巽為木，艮為闕。木在闕上，宮室之象也。四本震爻，震為長子。五本坎爻，坎為隱伏。居尊而隱伏，鬼神之象。長子入闕升堂，祭祖禰之禮也。故曰王假有廟。二本離爻也。離為目，居正應五，故利見大人矣。大牲，牛也。言大人有嘉會時可幹事，必殺牛而盟，既盟則可以往，故曰利往。</p><p>案：坤為牛，巽木下剋坤土，殺牛之象也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：萃，聚也，順以說，剛中而應，故聚也。王假有廟，致孝享也。利見大人亨，聚以正也。利貞。用大牲吉，利有攸往，順天命也。觀其所聚，而天地萬物之情可見矣。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>荀爽曰：謂五以剛居中，群陰順悅而從之，故能聚眾也。</p><p>陸績曰：王，五。廟，上也。王者聚百物以祭其先，諸侯助祭於廟中。假，大也。言五親奉上矣。</p><p>虞翻曰：享，享祀也。五至初，有觀象，謂享坤牛，故致孝享矣。</p><p>虞翻曰：坤為聚，坤三之四，故聚以正也。</p><p>《九家易》曰：五以正聚陽，故曰利貞。</p><p>虞翻曰：坤為順，巽為命，三往之四，故順天命也。</p><p>虞翻曰：三四易位成離坎。坎月離日，日以見天，月以見地，故天地之情可見也。與大壯、咸、恆同義也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：澤上於地，萃。君子以除戎器，戒不虞。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：澤者卑下，流潦歸之，萬物生焉，故謂之萃也。</p><p>虞翻曰：君子謂五。除，修，戎，兵也，《詩》曰：修爾車馬，弓矢戎兵。陽在三四為脩。坤為器。三四之正，離為戎兵、甲胄、飛矢。坎為弓弧，巽為繩。艮為石，謂敹甲胄，鍛厲矛矢。故除戎器也。坎為寇，坤為亂，故戒不虞也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，有孚不終，乃亂乃萃。若號，一握為笑，勿恤，往無咎。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：孚，謂五也。初四易位，五坎中，故有孚。失正當變，坤為終，故不終。萃。聚也。坤為亂為聚，故乃亂乃萃。失位不變，則相聚為亂。故《象》曰｢其志亂｣也。</p><p>虞翻曰：巽為號，艮為手，初稱一，故一握。初動成震，震為笑。四動成坎，坎為恤。故｢若號一握為笑，勿恤｣。初之四得正，故往無咎矣。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：乃亂乃萃，其志亂也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：坎為志，初不之四，其志亂也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，引吉，無咎。孚乃利用禴。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>虞翻曰：應巽為繩，艮為手，故引吉。得正應五，故無咎。利引四之初，使避已，已得之五也。</p><p>虞翻曰：孚謂五。禴，夏祭也。體觀象，故利用禴。四之三，故用大牲。離為夏，故禴祭，《詩》曰：禴祠烝嘗，是其義。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：引吉無咎，中未變也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：二得正，故不變也。</p><p>王弼曰：居萃之時，體柔當位。處坤之中，已獨履正。與眾相殊，異操而聚。民之多僻，獨正者危。未能變體，以遠於害，故必待五引，然後乃吉而無咎。禴，殷春祭名，四時之祭省者也。居聚之時，處於中正，而行以忠信，可以省薄於鬼神矣。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，萃如嗟如，無攸利，往無咎，小吝。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：坤為萃，故萃如。巽為號，故嗟如。失正，故無攸利。動得位故｢往無咎，小吝｣。謂往之四。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：往無咎，上巽也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：動之四，故上巽。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，大吉無咎。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：大吉無咎，位不當也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：以陽居陰，故位不當。動而得正，承五應初，故大吉而無咎矣。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，萃有位，無咎，匪孚。元永貞，悔亡。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：得位居中，故有位無咎。匪孚，謂四也。四變之正，則五體皆正，故元永貞與比彖同義。四動之初，故悔亡。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：萃有位，志未光也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：陽在坎中，故志未光。與屯五同義。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，齎咨涕洟，無咎。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：齎，持。資，賻也。貨財喪稱賻。自目曰涕，自鼻稱洟。坤為財，巽為進，故齎資也。三之四，體離坎。艮為鼻，涕淚流鼻目，故涕洟。得位應三，故無咎。上體大過，死象，故有齎資滋洟之哀。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：齎咨涕洟，未安上也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：乘剛遠應，故未安上也。</p><p>荀爽曰：此本否卦。上九陽爻，見滅遷移，以喻夏桀殷紂。以上六陰爻代之，若夏之後封東婁公於杞，殷之後封微子於宋，去其骨肉，臣服異姓，受人封土，未安居位，故曰｢齎咨涕洟，未安上也｣。</p>',77)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
